{
  "name": "emberfall-vale",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Emberfall Vale — a cozy 3D fantasy farming adventure",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build --base ./",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "0.160.0"
  },
  "devDependencies": {
    "vite": "^5.4.11"
  }
}

:root {
  --gold: #efcf8a;
  --gold-dim: #b9975b;
  --cream: #f6eedd;
  --ink: #0b111d;
  --panel: rgba(14, 22, 36, 0.94);
  --panel-2: rgba(23, 34, 52, 0.96);
  --line: rgba(239, 207, 138, 0.28);
  --green: #7fd6a8;
  --blue: #8fd0ff;
  --red: #ff8b7e;
  --shadow: 0 18px 60px rgba(0, 0, 0, 0.55);
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: ui-rounded, "SF Pro Rounded", "Segoe UI", system-ui, sans-serif;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  overflow: hidden; background: #0a0f19; color: var(--cream);
  font-family: var(--sans);
  overscroll-behavior: none;
  touch-action: none;
  user-select: none; -webkit-user-select: none;
}

#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

#vignette {
  position: fixed; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 45%, rgba(5, 8, 15, 0.34) 100%),
    linear-gradient(to bottom, rgba(5, 8, 15, 0.16), transparent 18%, transparent 82%, rgba(5, 8, 15, 0.3));
}

.hidden { display: none !important; }

/* ============ HUD ============ */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; }

.hud-top-left {
  position: absolute;
  top: calc(12px + var(--safe-t));
  left: calc(14px + var(--safe-l));
  display: flex; flex-direction: column; gap: 7px;
  width: min(290px, 44vw);
  filter: drop-shadow(0 4px 14px rgba(0,0,0,.45));
}

.nameplate {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  font-family: var(--serif); letter-spacing: .04em;
  background: linear-gradient(135deg, rgba(17, 27, 44, .9), rgba(12, 20, 33, .78));
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 6px 11px;
  font-size: clamp(11px, 1.5vw, 14px);
  color: var(--gold);
  backdrop-filter: blur(8px);
}
.nameplate .weather { margin-left: auto; color: #cfe1ec; font-size: .92em; }

.vitals { display: flex; flex-direction: column; gap: 4px; padding: 0 2px; }
.bar-row { display: flex; align-items: center; gap: 6px; }
.bar-ico { width: 15px; text-align: center; font-size: 11px; opacity: .95; }
.bar {
  flex: 1; height: 9px; border-radius: 6px; overflow: hidden;
  background: rgba(6, 10, 17, .72);
  border: 1px solid rgba(255,255,255,.12);
  box-shadow: inset 0 1px 3px rgba(0,0,0,.6);
}
.bar i { display: block; height: 100%; width: 100%; border-radius: 6px; transition: width .28s ease; }
.bar.health i { background: linear-gradient(90deg, #a8353e, #ff7e70); }
.bar.energy i { background: linear-gradient(90deg, #2f8d72, #9be9a6); }
.bar.low i { animation: pulseBar .8s ease-in-out infinite alternate; }
@keyframes pulseBar { to { filter: brightness(1.6); } }

.purse {
  display: flex; gap: 5px; flex-wrap: wrap; align-items: center;
  font-family: var(--serif); font-size: clamp(11px, 1.5vw, 14px);
}
.purse > span {
  background: rgba(12, 20, 33, .82);
  border: 1px solid var(--line);
  border-radius: 7px; padding: 3px 8px;
  color: var(--cream);
  backdrop-filter: blur(6px);
}
.purse .gem { color: #ffd77a; }
.purse .star { color: #9be8ff; }
.purse .mats { display: flex; gap: 7px; font-size: .9em; color: #c9d6e4; }
.purse .mats b { color: #e9f1f8; font-weight: 600; }

.quest-tracker {
  margin-top: 3px;
  background: linear-gradient(135deg, rgba(23, 35, 52, .9), rgba(13, 22, 35, .82));
  border: 1px solid var(--line);
  border-left: 3px solid var(--gold-dim);
  border-radius: 9px;
  padding: 7px 10px 8px;
  font-size: clamp(10px, 1.3vw, 12px);
  line-height: 1.35;
  backdrop-filter: blur(8px);
  transition: opacity .3s;
}
.qt-label { font-family: var(--serif); letter-spacing: .18em; color: var(--gold-dim); font-size: .78em; }
.qt-title { font-family: var(--serif); color: var(--gold); font-size: 1.06em; margin: 1px 0; }
.qt-desc { color: #bfcedb; }

.hud-top-right {
  position: absolute; top: calc(12px + var(--safe-t)); right: calc(14px + var(--safe-r));
  display: flex; align-items: flex-start; gap: 8px;
}
.clock-wrap {
  display: flex; flex-direction: column; align-items: flex-end; gap: 4px;
  background: linear-gradient(135deg, rgba(17, 27, 44, .9), rgba(12, 20, 33, .78));
  border: 1px solid var(--line);
  border-radius: 10px; padding: 6px 10px;
  backdrop-filter: blur(8px);
}
.clock { font-family: var(--serif); color: var(--gold); font-size: clamp(13px, 1.7vw, 17px); letter-spacing: .05em; }
.daytrack { width: 74px; height: 4px; border-radius: 3px; background: rgba(0,0,0,.5); overflow: hidden; }
.daytrack-fill { height: 100%; width: 10%; background: linear-gradient(90deg, #ffd37a, #ff9b6a); border-radius: 3px; transition: width .3s linear; }

.round-btn {
  pointer-events: auto;
  width: 42px; height: 42px; border-radius: 50%;
  border: 1px solid var(--line);
  background: linear-gradient(135deg, rgba(23, 35, 52, .94), rgba(12, 20, 33, .9));
  color: var(--gold); font-size: 19px; cursor: pointer;
  box-shadow: 0 5px 16px rgba(0,0,0,.4);
  backdrop-filter: blur(8px);
  transition: transform .12s, background .2s;
}
.round-btn:active { transform: scale(.94); }

.prompt {
  position: absolute; left: 50%; bottom: calc(122px + var(--safe-b));
  transform: translateX(-50%);
  display: flex; align-items: center; gap: 8px;
  background: rgba(11, 18, 30, .88);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 14px 6px 7px;
  font-size: 13px; letter-spacing: .02em;
  color: #f2eadb;
  backdrop-filter: blur(8px);
  box-shadow: 0 6px 22px rgba(0,0,0,.4);
  white-space: nowrap;
  transition: opacity .18s, transform .18s;
}
.prompt.hidden { display: none; }
.prompt-key {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 24px; height: 24px; border-radius: 6px;
  background: linear-gradient(180deg, #43536b, #243044);
  border: 1px solid rgba(255,255,255,.25);
  color: var(--gold); font-size: 11px; font-weight: 700;
  box-shadow: 0 2px 0 rgba(0,0,0,.4);
}

/* joystick */
#joystick {
  position: absolute; left: calc(26px + var(--safe-l)); bottom: calc(26px + var(--safe-b));
  width: 126px; height: 126px; border-radius: 50%;
  pointer-events: auto; touch-action: none;
  display: none;
  background: radial-gradient(circle at 50% 45%, rgba(255,255,255,.05), rgba(8,14,24,.36) 70%);
  border: 1.5px solid rgba(239, 207, 138, .22);
  box-shadow: inset 0 0 26px rgba(0,0,0,.35);
}
.joy-ring { position: absolute; inset: 20px; border-radius: 50%; border: 1px dashed rgba(239, 207, 138, .16); }
.joy-stick {
  position: absolute; left: 50%; top: 50%; width: 56px; height: 56px; margin: -28px 0 0 -28px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, #54637a, #1d283a 70%);
  border: 1.5px solid rgba(239, 207, 138, .5);
  box-shadow: 0 5px 16px rgba(0,0,0,.5), inset 0 1px 2px rgba(255,255,255,.25);
  transition: transform .05s linear;
}
@media (pointer: coarse), (max-width: 860px) {
  #joystick { display: block; }
}

/* actions */
#action-cluster {
  position: absolute; right: calc(22px + var(--safe-r)); bottom: calc(24px + var(--safe-b));
  display: flex; align-items: flex-end; gap: 13px;
  pointer-events: none;
}
.action-btn {
  pointer-events: auto; touch-action: none;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  border-radius: 50%; cursor: pointer; color: var(--cream);
  border: 1.5px solid rgba(239, 207, 138, .45);
  background: radial-gradient(circle at 38% 30%, rgba(57, 74, 96, .96), rgba(16, 25, 39, .94) 72%);
  box-shadow: 0 8px 24px rgba(0,0,0,.48), inset 0 1px 2px rgba(255,255,255,.18);
  transition: transform .1s ease, filter .2s;
}
.action-btn .ico { font-size: 24px; line-height: 1; filter: drop-shadow(0 2px 4px rgba(0,0,0,.5)); }
.action-btn .lbl { font-size: 9px; letter-spacing: .1em; text-transform: uppercase; color: #e9dcbf; }
.action-btn:active { transform: scale(.92); }
.action-btn.attack { width: 66px; height: 66px; }
.action-btn.interact { width: 88px; height: 88px; border-color: rgba(126, 226, 178, .55); }
.action-btn.interact .ico { font-size: 30px; }
.action-btn.interact:not(.disabled) { box-shadow: 0 0 0 2px rgba(126, 226, 178, .16), 0 0 28px rgba(126, 226, 178, .18), 0 8px 24px rgba(0,0,0,.48); }
.action-btn.disabled { filter: grayscale(.8) brightness(.66); }
.action-btn.attack.cool { filter: brightness(.7); }

.hotbar {
  position: absolute; left: 50%; bottom: calc(18px + var(--safe-b)); transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  pointer-events: none;
}
.hotbar-label { font-family: var(--serif); font-size: 9px; letter-spacing: .28em; color: rgba(239,207,138,.62); }
.slots { display: flex; gap: 7px; pointer-events: auto; }
.slot {
  position: relative; width: 58px; height: 58px; border-radius: 12px;
  background: linear-gradient(160deg, rgba(29, 42, 61, .92), rgba(13, 21, 34, .94));
  border: 1px solid rgba(239, 207, 138, .26);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  cursor: pointer; touch-action: manipulation;
  transition: transform .12s, border-color .2s, box-shadow .2s;
  box-shadow: 0 5px 16px rgba(0,0,0,.4);
}
.slot .seed { font-size: 23px; line-height: 1; filter: drop-shadow(0 2px 5px rgba(0,0,0,.45)); }
.slot .qty {
  position: absolute; right: 5px; bottom: 3px; font-size: 10px; font-weight: 700;
  color: #f4ecd9; text-shadow: 0 1px 3px #000;
}
.slot .nm { font-size: 8px; letter-spacing: .04em; color: #b9c9d8; margin-top: 2px; }
.slot .key { position: absolute; left: 5px; top: 3px; font-size: 8px; color: #8fa0b3; }
.slot.sel { border-color: var(--gold); box-shadow: 0 0 0 1px var(--gold), 0 0 18px rgba(239, 207, 138, .24), 0 5px 16px rgba(0,0,0,.4); transform: translateY(-3px); }
.slot.empty { opacity: .46; }

.hint {
  position: absolute; left: 50%; bottom: calc(88px + var(--safe-b)); transform: translateX(-50%);
  font-size: 11px; color: #cfdbe6; background: rgba(9,15,25,.6);
  border: 1px solid rgba(255,255,255,.08); border-radius: 8px; padding: 4px 10px;
  opacity: 0; transition: opacity .4s; white-space: nowrap; pointer-events: none;
}
.hint.show { opacity: 1; }

.minimap-charm {
  position: absolute; right: calc(20px + var(--safe-r)); bottom: calc(210px + var(--safe-b));
  width: 42px; height: 42px; border-radius: 50%;
  border: 1px solid var(--line);
  background: radial-gradient(circle, rgba(29, 45, 66, .82), rgba(9, 15, 25, .8));
  color: rgba(239, 207, 138, .55); display: none;
  align-items: center; justify-content: center; font-size: 14px;
}
@media (pointer: coarse), (max-width: 860px) {
  .minimap-charm { display: flex; }
}
.minimap-charm .needle { position: absolute; inset: 0; transition: transform .25s; }
.minimap-charm .needle::before {
  content: ""; position: absolute; left: 50%; top: 3px; margin-left: -2px;
  border-left: 4px solid transparent; border-right: 4px solid transparent; border-bottom: 8px solid #8fe8c5;
}

/* ============ Toasts & floats ============ */
#toasts {
  position: fixed; left: 50%; top: calc(72px + var(--safe-t)); transform: translateX(-50%);
  z-index: 60; display: flex; flex-direction: column; align-items: center; gap: 7px;
  pointer-events: none; width: min(88vw, 460px);
}
.toast {
  display: flex; align-items: center; gap: 9px;
  padding: 8px 14px; border-radius: 10px;
  background: linear-gradient(135deg, rgba(20, 32, 49, .96), rgba(11, 18, 30, .96));
  border: 1px solid var(--line);
  color: #f0e7d5; font-size: 12.5px; line-height: 1.3;
  box-shadow: 0 8px 28px rgba(0,0,0,.42);
  animation: toastIn .3s cubic-bezier(.2,1.4,.4,1) both;
  backdrop-filter: blur(10px);
  text-align: center;
}
.toast.out { animation: toastOut .35s ease forwards; }
.toast .ti { font-size: 17px; }
.toast.gold { border-color: rgba(239,207,138,.55); color: #ffe9b1; }
.toast.quest { border-color: rgba(126,226,178,.45); color: #c9f7de; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px) scale(.96); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px) scale(.97); } }

#floats { position: fixed; inset: 0; z-index: 55; pointer-events: none; overflow: hidden; }
.float {
  position: absolute; transform: translate(-50%, -50%);
  font-family: var(--serif); font-size: 14px; font-weight: 700; color: #ffe6a4;
  text-shadow: 0 2px 4px #000, 0 0 12px rgba(255,210,120,.4);
  animation: floatUp 1.15s ease-out forwards;
  white-space: nowrap;
}
.float.heal { color: #9bf0b8; }
.float.dmg { color: #ff8f83; }
.float.ess { color: #9be8ff; }
@keyframes floatUp {
  0% { opacity: 0; margin-top: 6px; }
  18% { opacity: 1; }
  100% { opacity: 0; margin-top: -44px; }
}

/* ============ Title screen ============ */
.screen { position: fixed; inset: 0; z-index: 40; }
.title-screen {
  display: flex; align-items: center; justify-content: flex-start;
  padding: calc(28px + var(--safe-t)) clamp(22px, 8vw, 120px) calc(28px + var(--safe-b));
  background:
    linear-gradient(100deg, rgba(5, 9, 16, .93) 0%, rgba(6, 11, 20, .78) 33%, rgba(6, 11, 20, .22) 62%, rgba(6, 11, 20, .05) 100%),
    radial-gradient(ellipse at 78% 30%, rgba(255, 190, 120, .12), transparent 55%);
  transition: opacity .8s ease;
}
.title-screen.gone { opacity: 0; pointer-events: none; }
.title-inner { max-width: 560px; }
.eyebrow {
  font-family: var(--serif); font-size: clamp(9px, 1.2vw, 11px);
  letter-spacing: .34em; color: #c9a96a; margin-bottom: 12px;
  text-shadow: 0 2px 8px #000;
}
.title-inner h1 {
  margin: 0; font-family: var(--serif); font-weight: 400;
  font-size: clamp(60px, 11vw, 118px); line-height: .82; letter-spacing: .02em;
  color: #f4e9cf;
  text-shadow: 0 4px 0 rgba(58, 36, 14, .55), 0 14px 44px rgba(0,0,0,.7);
}
.title-inner h1 span {
  display: inline-block; margin-left: .06em;
  background: linear-gradient(180deg, #ffe8a8 10%, #e9b665 55%, #b87c3e 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 16px rgba(255, 190, 100, .22));
}
.flourish { display: flex; align-items: center; gap: 10px; margin: 18px 0 14px; color: #d8b674; }
.flourish i { display: block; height: 1px; width: 62px; background: linear-gradient(90deg, transparent, #b8945a); }
.flourish i:last-child { background: linear-gradient(90deg, #b8945a, transparent); }
.flourish span { font-size: 12px; color: #f0d391; }
.tagline {
  font-size: clamp(12.5px, 1.5vw, 15px); line-height: 1.65; color: #c2cdd9;
  max-width: 460px; margin: 0 0 26px; text-shadow: 0 2px 10px #000;
}
.title-actions { display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
.btn {
  pointer-events: auto; cursor: pointer; border-radius: 10px;
  font-family: var(--serif); letter-spacing: .08em;
  transition: transform .15s, filter .2s, background .2s;
  min-width: 240px; padding: 13px 26px; font-size: 15px;
}
.btn:active { transform: scale(.975); }
.btn.primary {
  color: #1b140a; border: 1px solid #f3d79a;
  background: linear-gradient(180deg, #f6dfa5, #d9ae63 65%, #bd8a46);
  box-shadow: 0 5px 0 #6c4a22, 0 14px 30px rgba(0,0,0,.4), inset 0 1px 0 #fff2c8;
  text-shadow: 0 1px 0 rgba(255,255,255,.35);
}
.btn.primary:hover { filter: brightness(1.07); }
.btn.ghost {
