import * as THREE from 'three';
import { stdMat, glowSprite, angleLerp, clamp, damp } from './util.js';

export class Player {
  constructor(scene) {
    this.scene = scene;
    this.group = new THREE.Group();
    this.group.name = 'player';
    this.pos = new THREE.Vector3(0, 0, 12.4);
    this.facing = Math.PI;
    this.walkPhase = 0;
    this.attackTimer = 0;
    this.attackCooldown = 0;
    this.moving = false;
    this.hurtFlash = 0;
    this.build();
    scene.add(this.group);
  }

  build() {
    const g = this.group;
    const skin = stdMat({ color: '#e9c39c' });
    const tunic = stdMat({ color: '#3f7f74' });
    const tunicDark = stdMat({ color: '#2c5e57' });
    const pants = stdMat({ color: '#3a3f52' });
    const leather = stdMat({ color: '#75512f' });
    const hatMat = stdMat({ color: '#c9a05a' });
    const goldMat = stdMat({ color: '#e2c072', roughness: 0.5, metalness: 0.25 });
    const hairMat = stdMat({ color: '#6a4326' });
    const capeMat = stdMat({ color: '#2e5f68', side: THREE.DoubleSide });

    // legs (pivot groups)
    this.legL = new THREE.Group();
    this.legR = new THREE.Group();
    for (const [leg, x] of [[this.legL, -0.14], [this.legR, 0.14]]) {
      leg.position.set(x, 0.62, 0);
      const limb = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.5, 0.2), pants);
      limb.position.y = -0.25;
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.2, 0.32), leather);
      boot.position.set(0, -0.52, 0.05);
      limb.castShadow = true; boot.castShadow = true;
      leg.add(limb, boot);
      g.add(leg);
    }

    // tunic / body
    this.body = new THREE.Group();
    this.body.position.y = 0.62;
    const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.29, 0.4, 0.82, 7), tunic);
    torso.position.y = 0.4;
    torso.castShadow = true;
    const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.31, 0.34, 0.1, 8), leather);
    belt.position.y = 0.2;
    const buckle = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.1, 0.05), goldMat);
    buckle.position.set(0, 0.2, 0.33);
    const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.3, 0.16, 7), tunicDark);
    collar.position.y = 0.82;
    this.body.add(torso, belt, buckle, collar);

    // head
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.245, 11, 10), skin);
    head.position.y = 1.08;
    head.castShadow = true;
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.255, 11, 8, 0, Math.PI * 2, 0, Math.PI * 0.62), hairMat);
    hair.position.set(0, 1.13, -0.02);
    hair.rotation.x = -0.16;
    const nose = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.09, 4), skin);
    nose.position.set(0, 1.06, 0.24);
    nose.rotation.x = Math.PI / 2;
    for (const s of [-1, 1]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.028, 6, 5), new THREE.MeshBasicMaterial({ color: 0x2a241f }));
      eye.position.set(0.085 * s, 1.13, 0.215);
      this.body.add(eye);
    }
    this.body.add(head, hair, nose);

    // hat
    this.hat = new THREE.Group();
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.44, 0.055, 12), hatMat);
    brim.castShadow = true;
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.27, 0.52, 10), hatMat);
    cone.position.y = 0.27;
    cone.castShadow = true;
    const band = new THREE.Mesh(new THREE.CylinderGeometry(0.275, 0.29, 0.09, 10), tunicDark);
    band.position.y = 0.06;
    this.hat.add(brim, cone, band);
    this.hat.position.set(0, 1.27, 0);
    this.hat.rotation.z = 0.08;
    this.body.add(this.hat);

    // cape
    const capeGeo = new THREE.PlaneGeometry(0.5, 0.9, 1, 3);
    capeGeo.translate(0, -0.42, 0);
    this.cape = new THREE.Mesh(capeGeo, capeMat);
    this.cape.position.set(0, 0.78, -0.25);
    this.cape.rotation.x = 0.12;
    this.cape.castShadow = true;
    this.body.add(this.cape);

    // arms
    this.armL = new THREE.Group();
    this.armR = new THREE.Group();
    for (const [arm, x] of [[this.armL, -0.35], [this.armR, 0.35]]) {
      arm.position.set(x, 0.7, 0);
      const limb = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.46, 0.16), tunicDark);
      limb.position.y = -0.2;
      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.09, 7, 6), skin);
      hand.position.y = -0.45;
      limb.castShadow = true;
      arm.add(limb, hand);
      this.body.add(arm);
      arm.rotation.z = x > 0 ? -0.12 : 0.12;
    }

    // lantern in left hand
    this.lantern = glowSprite('#ffd08a', 1.1, 0.6);
    this.lantern.position.set(0, -0.52, 0.08);
    this.armL.add(this.lantern);
    const lampBody = new THREE.Mesh(
      new THREE.BoxGeometry(0.13, 0.18, 0.13),
      new THREE.MeshStandardMaterial({ color: '#ffdca2', emissive: '#ffb257', emissiveIntensity: 1.4 })
    );
    lampBody.position.set(0, -0.52, 0.08);
    this.armL.add(lampBody);
    this.lanternLight = new THREE.PointLight(0xffb96a, 0.9, 7, 2);
    this.lanternLight.position.set(0, 1.2, 0.3);
    g.add(this.lanternLight);

    // sword (hidden unless attacking)
    this.sword = new THREE.Group();
    const blade = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.72, 0.022), new THREE.MeshStandardMaterial({ color: '#d8e7ef', metalness: 0.7, roughness: 0.28, emissive: '#78d9ff', emissiveIntensity: 0.25 }));
    blade.position.y = 0.44;
    const guard = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.05, 0.06), goldMat);
    const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.18, 5), leather);
    grip.position.y = -0.11;
    this.sword.add(blade, guard, grip);
    this.sword.position.set(0, -0.48, 0.02);
    this.sword.rotation.x = Math.PI;
    this.sword.visible = false;
    this.armR.add(this.sword);

    // backpack
    const pack = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.42, 0.22), leather);
    pack.position.set(0, 0.45, -0.34);
    pack.castShadow = true;
    const roll = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.42, 6), stdMat({ color: '#8d6b42' }));
    roll.rotation.z = Math.PI / 2;
    roll.position.set(0, 0.72, -0.35);
    this.body.add(pack, roll);

    g.add(this.body);
    g.traverse((o) => { if (o.isMesh) o.castShadow = true; });
  }

  setPosition(x, y, z) {
    this.pos.set(x, y, z);
    this.group.position.set(x, y, z);
  }

  update(dt, moving, speed, hours) {
    this.moving = moving;
    if (this.attackTimer > 0) this.attackTimer = Math.max(0, this.attackTimer - dt);
    if (this.attackCooldown > 0) this.attackCooldown = Math.max(0, this.attackCooldown - dt);

    if (moving) {
      this.walkPhase += dt * (5.4 + speed * 0.9);
    } else {
      this.walkPhase += dt * 1.2;
    }
    const swing = moving ? Math.sin(this.walkPhase) * 0.62 : Math.sin(this.walkPhase * 0.6) * 0.04;
    this.legL.rotation.x = swing;
    this.legR.rotation.x = -swing;
    this.armL.rotation.x = -swing * 0.65;
    this.armR.rotation.x = swing * 0.65;

    const bob = moving ? Math.abs(Math.sin(this.walkPhase)) * 0.055 : Math.sin(this.walkPhase * 0.6) * 0.014;
    this.body.position.y = 0.62 + bob;
    this.cape.rotation.x = 0.1 + (moving ? 0.28 : 0.03) + Math.sin(this.walkPhase * 0.8) * 0.05;

    // attack swing overrides right arm
    if (this.attackTimer > 0) {
      const t = 1 - this.attackTimer / 0.34;
      const ang = -1.9 + t * 2.9;
      this.armR.rotation.x = ang;
      this.armR.rotation.z = -0.55 + t * 0.8;
      const atk = new THREE.Euler();
      atk.set(ang + 0.5, 0.2, 0);
      this.sword.rotation.set(Math.PI + ang * 0.55, 0.1, 0);
      this.sword.visible = true;
    } else {
      this.armR.rotation.z = damp(this.armR.rotation.z, -0.12, 8, dt);
      this.sword.visible = false;
    }

    // lantern flicker and night brightness
    const night = 1 - clamp(Math.sin(((hours - 6) / 24) * Math.PI * 2) * 1.6 + 0.35, 0, 1);
    this.lantern.material.opacity = 0.32 + night * 0.55 + Math.sin(performance.now() * 0.006) * 0.05;
    this.lanternLight.intensity = 0.25 + night * 1.1;
    this.group.position.x = this.pos.x;
    this.group.position.z = this.pos.z;
    this.group.position.y = this.pos.y;
  }

  faceTowards(tx, tz, dt) {
    const target = Math.atan2(tx - this.pos.x, tz - this.pos.z);
    this.facing = angleLerp(this.facing, target, 1 - Math.exp(-12 * dt));
    this.group.rotation.y = this.facing;
  }

  faceDirection(dx, dz, dt) {
    if (Math.abs(dx) + Math.abs(dz) < 0.001) return;
    const target = Math.atan2(dx, dz);
    this.facing = angleLerp(this.facing, target, 1 - Math.exp(-14 * dt));
    this.group.rotation.y = this.facing;
  }

  startAttack() {
    if (this.attackCooldown > 0) return false;
    this.attackCooldown = 0.48;
    this.attackTimer = 0.34;
    return true;
  }

  forward() {
    return { x: Math.sin(this.facing), z: Math.cos(this.facing) };
  }
}

import * as THREE from 'three';
import { rand, stdMat, clamp, glowSprite } from './util.js';

const SPAWNS = [
  { x: -22, z: -17 },
  { x: -25, z: 3 },
  { x: 25, z: -18 },
  { x: 27, z: 15 },
  { x: -14, z: 26 },
  { x: 9, z: -25 },
  { x: -30, z: -4 },
  { x: 32, z: 2 },
];

const PALETTES = [
  { body: '#5fbf8f', glow: '#7dffb8', eye: '#1d3a2b' },
  { body: '#7f8fe8', glow: '#b4c4ff', eye: '#232546' },
  { body: '#c67fd8', glow: '#f2a8ff', eye: '#3a1f45' },
  { body: '#d8b35f', glow: '#ffe28a', eye: '#3d2d12' },
];

export class SlimeManager {
  constructor(scene, world) {
    this.scene = scene;
    this.world = world;
    this.slimes = [];
    this.time = 0;
    SPAWNS.forEach((s, i) => {
      this.slimes.push(this.makeSlime(s.x, s.z, i));
    });
  }

  makeSlime(x, z, i) {
    const pal = PALETTES[i % PALETTES.length];
    const g = new THREE.Group();
    const bodyMat = new THREE.MeshStandardMaterial({
      color: pal.body, emissive: pal.glow, emissiveIntensity: 0.32,
      roughness: 0.55, flatShading: true,
    });
    const body = new THREE.Mesh(new THREE.IcosahedronGeometry(0.5, 1), bodyMat);
    body.scale.set(1.05, 0.82, 1.05);
    body.position.y = 0.4;
    body.castShadow = true;
    const belly = new THREE.Mesh(
      new THREE.SphereGeometry(0.36, 9, 7),
      new THREE.MeshStandardMaterial({ color: '#e8fff2', emissive: pal.glow, emissiveIntensity: 0.18, roughness: 0.7 })
    );
    belly.scale.set(1, 0.38, 1);
    belly.position.y = 0.14;
    const eyes = [];
    for (const s of [-1, 1]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.09, 7, 6), new THREE.MeshBasicMaterial({ color: 0xffffff }));
      eye.position.set(0.16 * s, 0.5, 0.4);
      const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.045, 6, 5), new THREE.MeshBasicMaterial({ color: pal.eye }));
      pupil.position.set(0.16 * s, 0.5, 0.47);
      g.add(eye, pupil);
      eyes.push(eye);
    }
    const glow = glowSprite(pal.glow, 2.0, 0.35);
    glow.position.y = 0.4;
    g.add(body, belly, glow);

    const y = this.world.height(x, z);
    g.position.set(x, y, z);
    this.scene.add(g);

    return {
      group: g, body, belly, bodyMat, glow, x, z, homeX: x, homeZ: z,
      y, hp: 3, maxHp: 3, alive: true, hop: rand(0, 6.28), phase: 'wander',
      wander: { x, z }, timer: rand(1, 4), hurt: 0, cooldown: 0,
      speed: rand(1.5, 2.1), size: 1, knockX: 0, knockZ: 0,
    };
  }

  resetDay(day) {
    for (const s of this.slimes) {
      s.alive = true;
      s.hp = s.maxHp;
      s.group.visible = true;
      s.group.scale.setScalar(1);
      s.x = s.homeX;
      s.z = s.homeZ;
      s.hurt = 0;
      s.cooldown = 0;
      s.phase = 'wander';
      s.timer = rand(0.5, 2);
    }
  }

  hit(slime, dirX, dirZ) {
    if (!slime.alive) return false;
    slime.hp -= 1;
    slime.hurt = 0.18;
    slime.knockX = dirX * 3.2;
    slime.knockZ = dirZ * 3.2;
    slime.phase = 'chase';
    return slime.hp <= 0;
  }

  kill(slime) {
    slime.alive = false;
    slime.group.visible = false;
  }

  update(dt, playerPos, game) {
    this.time += dt;
    const t = this.time;
    for (const s of this.slimes) {
      if (!s.alive) continue;
      const dx = playerPos.x - s.x, dz = playerPos.z - s.z;
      const dist = Math.hypot(dx, dz);
      s.timer -= dt;
      if (s.cooldown > 0) s.cooldown -= dt;
      if (s.hurt > 0) s.hurt -= dt;

      // knockback
      if (Math.abs(s.knockX) + Math.abs(s.knockZ) > 0.01) {
        s.x += s.knockX * dt;
        s.z += s.knockZ * dt;
        s.knockX *= Math.pow(0.02, dt);
        s.knockZ *= Math.pow(0.02, dt);
      }

      let moving = false;
      if (dist < 7.2 && game.state.hours > 17.5) s.phase = 'chase';
      if (dist < 5.2) s.phase = 'chase';
      if (s.phase === 'chase' && dist > 11) s.phase = 'wander';

      if (s.phase === 'chase' && dist > 0.01) {
        const sp = s.speed * (dist < 2 ? 0.8 : 1);
        s.x += (dx / dist) * sp * dt;
        s.z += (dz / dist) * sp * dt;
        moving = true;
        // contact damage
        if (dist < 1.15 && s.cooldown <= 0) {
          s.cooldown = 1.15;
          game.damagePlayer(8 + (s.maxHp - 3) * 2, s.x, s.z);
          game.sfx('hit');
        }
      } else if (s.timer <= 0) {
        s.timer = rand(2.2, 5.2);
        const a = rand(0, Math.PI * 2), r = rand(2, 8);
        s.wander.x = s.homeX + Math.cos(a) * r;
        s.wander.z = s.homeZ + Math.sin(a) * r;
      } else {
        const wdx = s.wander.x - s.x, wdz = s.wander.z - s.z;
        const wd = Math.hypot(wdx, wdz);
        if (wd > 0.4) {
          s.x += (wdx / wd) * s.speed * 0.42 * dt;
          s.z += (wdz / wd) * s.speed * 0.42 * dt;
          moving = true;
        }
      }

      // keep in bounds
      const rr = Math.hypot(s.x, s.z);
      if (rr > 54) { s.x *= 54 / rr; s.z *= 54 / rr; }

      s.y = this.world.height(s.x, s.z);
      s.hop += dt * (moving ? 6.2 : 2.6);
      const hop = moving ? Math.abs(Math.sin(s.hop)) * 0.34 : 0;
      const squash = moving ? Math.sin(s.hop * 2) * 0.06 : Math.sin(t * 1.5 + s.homeX) * 0.025;
      s.group.position.set(s.x, s.y + hop + 0.02, s.z);
      s.body.scale.set(1.05 + squash, 0.82 - squash * 0.7, 1.05 + squash);
      s.belly.scale.set(1 + squash, 0.38, 1 + squash);
      const targetRot = dist > 0.1 && s.phase === 'chase' ? Math.atan2(dx, dz) : Math.atan2(s.wander.x - s.x, s.wander.z - s.z);
      s.group.rotation.y += (targetRot - s.group.rotation.y) * Math.min(1, dt * 8);

      if (s.hurt > 0) {
        s.bodyMat.emissiveIntensity = 1.6;
        s.body.scale.x += 0.1;
      } else {
        s.bodyMat.emissiveIntensity = 0.32 + Math.sin(t * 2 + s.homeX) * 0.05;
      }
      const night = game.state.hours > 18 || game.state.hours < 6;
      s.glow.material.opacity = 0.18 + (night ? 0.4 : 0.1) + Math.sin(t * 3 + s.homeX) * 0.06;
      s.glow.scale.setScalar(1.8 + Math.sin(t * 2 + s.homeX) * 0.2);
    }
  }
}

// Tiny procedural sound engine — no external assets.
export class Audio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noiseBuffer = null;
    this.ambient = null;
    this.lastChirp = 0;
  }

  init() {
    if (this.ctx) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.32;
    this.master.connect(this.ctx.destination);
    this.makeNoise();
    this.startAmbient();
  }

  makeNoise() {
    const len = this.ctx.sampleRate * 2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buf;
  }

  setMuted(m) {
    this.muted = m;
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.32, this.ctx.currentTime, 0.05);
  }

  startAmbient() {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 340;
    const gain = this.ctx.createGain();
    gain.gain.value = 0.055;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();
    this.ambient = { src, filter, gain };

    // soft sustained pad
    const padGain = this.ctx.createGain();
    padGain.gain.value = 0.018;
    padGain.connect(this.master);
    for (const f of [110, 164.81, 220]) {
      const o = this.ctx.createOscillator();
      o.type = 'sine';
      o.frequency.value = f;
      const g = this.ctx.createGain();
      g.gain.value = 0.33;
      o.connect(g).connect(padGain);
      o.start();
    }
    this.pad = padGain;
  }

  updateAmbient(hours, night) {
    if (!this.ctx || this.muted) return;
    if (this.ambient) {
      const target = night ? 200 : 380;
      this.ambient.filter.frequency.setTargetAtTime(target, this.ctx.currentTime, 2);
      this.ambient.gain.gain.setTargetAtTime(night ? 0.04 : 0.06, this.ctx.currentTime, 2);
    }
    const now = this.ctx.currentTime;
    if (now - this.lastChirp > (night ? 2.4 : 4.2)) {
      this.lastChirp = now + Math.random() * 2;
      if (Math.random() < 0.7) {
        if (night) this.cricket();
        else this.bird();
      }
    }
  }

  bird() {
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'sine';
    const base = 1700 + Math.random() * 900;
    o.frequency.setValueAtTime(base, t);
    o.frequency.exponentialRampToValueAtTime(base * 1.5, t + 0.07);
    o.frequency.exponentialRampToValueAtTime(base * 1.1, t + 0.16);
    g.gain.setValueAtTime(0.0, t);
    g.gain.linearRampToValueAtTime(0.035, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.22);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + 0.25);
  }

  cricket() {
    const t = this.ctx.currentTime;
    for (let i = 0; i < 3; i++) {
      const o = this.ctx.createOscillator();
      const g = this.ctx.createGain();
      o.type = 'triangle';
      o.frequency.value = 3200 + Math.random() * 300;
      const st = t + i * 0.08;
      g.gain.setValueAtTime(0, st);
      g.gain.linearRampToValueAtTime(0.013, st + 0.01);
      g.gain.exponentialRampToValueAtTime(0.001, st + 0.06);
      o.connect(g).connect(this.master);
      o.start(st); o.stop(st + 0.08);
    }
  }

  noise(duration, freq, q, gain = 0.2, type = 'bandpass', sweepTo = null) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    if (sweepTo) f.frequency.exponentialRampToValueAtTime(sweepTo, t + duration);
    f.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(f).connect(g).connect(this.master);
    src.start(t);
    src.stop(t + duration + 0.02);
  }

  tone(freq, duration, type = 'sine', gain = 0.12, delay = 0, slideTo = null) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + duration);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    o.connect(g).connect(this.master);
    o.start(t); o.stop(t + duration + 0.02);
  }

  sfx(name) {
    if (!this.ctx || this.muted) return;
    switch (name) {
      case 'step':
        this.noise(0.09, 220, 0.7, 0.05, 'lowpass');
        break;
      case 'till':
        this.noise(0.2, 420, 0.8, 0.16, 'lowpass');
        this.tone(90, 0.12, 'sine', 0.05);
        break;
      case 'plant':
        this.tone(520, 0.1, 'sine', 0.07, 0, 700);
        this.noise(0.12, 900, 1, 0.05);
        break;
      case 'water':
        this.noise(0.45, 1800, 0.6, 0.12, 'bandpass', 700);
        break;
      case 'harvest':
        this.tone(660, 0.18, 'sine', 0.09);
        this.tone(880, 0.22, 'sine', 0.08, 0.07);
        this.tone(1320, 0.3, 'triangle', 0.06, 0.14);
        break;
      case 'chop':
        this.noise(0.14, 260, 0.7, 0.2, 'lowpass');
        this.tone(110, 0.12, 'square', 0.05);
        break;
      case 'mine':
        this.tone(880, 0.08, 'square', 0.04, 0, 400);
        this.noise(0.12, 2400, 1.4, 0.13);
        break;
      case 'attack':
        this.noise(0.18, 900, 0.7, 0.14, 'bandpass', 2600);
        break;
      case 'hit':
        this.tone(150, 0.14, 'square', 0.08, 0, 70);
        this.noise(0.1, 400, 0.8, 0.12);
        break;
      case 'slime':
        this.tone(300, 0.16, 'sine', 0.08, 0, 520);
        this.tone(200, 0.2, 'triangle', 0.05, 0.04);
        break;
      case 'coin':
        this.tone(1046, 0.1, 'triangle', 0.07);
        this.tone(1568, 0.16, 'triangle', 0.06, 0.06);
        break;
      case 'click':
        this.tone(520, 0.05, 'sine', 0.05);
        break;
      case 'quest':
        [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.06, i * 0.1));
        break;
      case 'magic':
        [392, 523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.8, 'sine', 0.045, i * 0.07));
        break;
      case 'sleep':
        [523, 392, 330, 262].forEach((f, i) => this.tone(f, 0.7, 'sine', 0.06, i * 0.18));
        break;
      case 'hurt':
        this.tone(220, 0.2, 'sawtooth', 0.07, 0, 110);
        this.noise(0.14, 500, 0.8, 0.1);
        break;
      case 'error':
        this.tone(180, 0.12, 'square', 0.04);
        break;
      default:
        break;
    }
  }
}

import * as THREE from 'three';

const $ = (id) => document.getElementById(id);

export const CROPS = {
  moon: { name: 'Moonpetal', icon: '🌙', color: '#bfe9ff', sell: 58, grow: 2, seedName: 'Moonpetal Seed' },
  sun: { name: 'Sunberry', icon: '☀️', color: '#ffd166', sell: 126, grow: 3, seedName: 'Sunberry Seed' },
  star: { name: 'Starcorn', icon: '⭐', color: '#ffe9a3', sell: 275, grow: 4, seedName: 'Starcorn Seed' },
};

export class UI {
  constructor(game) {
    this.game = game;
    this.toastEl = $('toasts');
    this.floatEl = $('floats');
    this.modal = $('modal-root');
    this.hintTimer = null;
    this.modalKind = null;
    this.questTab = 'quests';
    this.shopTab = 'buy';
    this.bind();
    this.buildSeedSlots();
  }

  bind() {
    const tap = (id, fn) => {
      const el = $(id);
      if (!el) return;
      el.addEventListener('click', (e) => { e.preventDefault(); this.game.audio.init(); this.game.audio.sfx('click'); fn(e); });
    };
    tap('btn-menu', () => this.game.openMenu());
    tap('btn-action', () => this.game.doAction());
    tap('btn-attack', () => this.game.doAttack());
    tap('btn-new', () => this.game.startNew());
    tap('btn-continue', () => this.game.continueGame());
    tap('btn-how', () => this.openHelp());
    tap('btn-attack', () => this.game.doAttack());

    // joystick
    const joy = $('joystick');
    const stick = $('stick');
    let active = false, pid = null;
    const center = () => {
      const r = joy.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2, rad: r.width * 0.33 };
    };
    const move = (e) => {
      if (!active || e.pointerId !== pid) return;
      const c = center();
      let dx = e.clientX - c.x, dy = e.clientY - c.y;
      const len = Math.hypot(dx, dy);
      const max = c.rad;
      if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
      stick.style.transform = `translate(${dx}px, ${dy}px)`;
      this.game.joystick.x = dx / max;
      this.game.joystick.y = dy / max;
    };
    joy.addEventListener('pointerdown', (e) => {
      active = true; pid = e.pointerId;
      joy.setPointerCapture(e.pointerId);
      this.game.audio.init();
      move(e);
    });
    joy.addEventListener('pointermove', move);
    const end = (e) => {
      if (e.pointerId !== pid) return;
      active = false; pid = null;
      stick.style.transform = 'translate(0px, 0px)';
      this.game.joystick.x = 0; this.game.joystick.y = 0;
    };
    joy.addEventListener('pointerup', end);
    joy.addEventListener('pointercancel', end);
    joy.addEventListener('lostpointercapture', end);

    // modal close
    this.modal.addEventListener('click', (e) => {
      if (e.target === this.modal && this.modalKind !== 'win' && this.modalKind !== 'summary') this.closeModal();
    });
    this.modal.addEventListener('click', (e) => {
      const close = e.target.closest('[data-close]');
      if (close) this.closeModal();
    });
    this.modal.addEventListener('click', (e) => {
      const tab = e.target.closest('[data-tab]');
      if (tab) {
        this.shopTab = tab.dataset.tab;
        this.renderShop();
      }
      const qtab = e.target.closest('[data-qtab]');
      if (qtab) {
        this.questTab = qtab.dataset.qtab;
        this.renderMenu();
      }
    });
  }

  buildSeedSlots() {
    const wrap = $('seed-slots');
    wrap.innerHTML = '';
    const order = ['moon', 'sun', 'star'];
    order.forEach((type, i) => {
      const c = CROPS[type];
      const el = document.createElement('button');
      el.className = 'slot';
      el.dataset.seed = type;
      el.innerHTML = `<span class="key">${i + 1}</span><span class="seed">${c.icon}</span><span class="qty">0</span><span class="nm">${c.name}</span>`;
      el.addEventListener('click', (e) => {
        e.preventDefault();
        this.game.audio.init();
        this.game.selectSeed(type);
      });
      wrap.appendChild(el);
    });
  }

  // ---------------- HUD ----------------
  setHudVisible(v) {
    const hud = $('hud');
    hud.classList.toggle('hidden', !v);
    hud.setAttribute('aria-hidden', v ? 'false' : 'true');
  }

  hideTitle() {
    const t = $('screen-title');
    t.classList.add('gone');
    setTimeout(() => t.classList.add('hidden'), 900);
  }

  showTitle(hasSave) {
    const t = $('screen-title');
    t.classList.remove('hidden', 'gone');
    $('btn-continue').classList.toggle('hidden', !hasSave);
    $('btn-new').textContent = hasSave ? 'New Journey' : 'Begin Anew';
  }

  update(state) {
    const s = state;
    $('hud-date').textContent = `${s.season} · Day ${s.day}`;
    $('hud-weather').textContent = s.weather === 'rain' ? '🌧 Rain' : s.hours > 19 || s.hours < 6 ? '🌙 Clear' : '☀ Clear';
    const h = Math.floor(s.hours) % 24;
    const m = Math.floor((s.hours % 1) * 60);
    const ampm = h >= 12 ? 'PM' : 'AM';
    const h12 = h % 12 === 0 ? 12 : h % 12;
    $('hud-clock').textContent = `${h12}:${String(m).padStart(2, '0')} ${ampm}`;
    $('daytrack').style.width = `${Math.min(100, Math.max(0, ((s.hours - 6) / 18) * 100))}%`;
    $('hud-gold').textContent = Math.floor(s.gold);
    $('hud-essence').textContent = Math.floor(s.essence);
    $('hud-wood').textContent = Math.floor(s.wood);
    $('hud-stone').textContent = Math.floor(s.stone);
    $('bar-health').style.width = `${Math.max(0, (s.health / s.maxHealth) * 100)}%`;
    $('bar-energy').style.width = `${Math.max(0, (s.energy / s.maxEnergy) * 100)}%`;
    $('bar-health').parentElement.classList.toggle('low', s.health / s.maxHealth < 0.3);
    $('bar-energy').parentElement.classList.toggle('low', s.energy / s.maxEnergy < 0.25);
    this.updateSeeds(s);
    this.updateQuestChip(s);
    // compass: point at wizard tower
    const dx = 15.5 - this.game.player.pos.x, dz = 6.5 - this.game.player.pos.z;
    const ang = Math.atan2(dx, dz) - this.game.cameraYaw;
    const needle = $('needle');
    if (needle) needle.style.transform = `rotate(${ang}rad)`;
  }

  updateSeeds(s) {
    document.querySelectorAll('.slot').forEach((el) => {
      const type = el.dataset.seed;
      const qty = s.seeds[type] || 0;
      el.querySelector('.qty').textContent = qty;
      el.classList.toggle('sel', s.selectedSeed === type);
      el.classList.toggle('empty', qty <= 0);
    });
  }

  updateQuestChip(s) {
    const q = this.game.currentQuest();
    if (!q) {
      $('qt-title').textContent = 'The Vale Thrives';
      $('qt-desc').textContent = 'Free play — grow, explore, and prosper.';
      return;
    }
    $('qt-title').textContent = q.name;
    $('qt-desc').textContent = q.desc;
  }

  setPrompt(text, key = 'E') {
    const p = $('prompt');
    if (!text) { p.classList.add('hidden'); return; }
    p.classList.remove('hidden');
    $('prompt-key').textContent = key;
    $('prompt-text').textContent = text;
  }

  setAction(icon, label, enabled) {
    $('action-icon').textContent = icon;
    $('action-label').textContent = label;
    $('btn-action').classList.toggle('disabled', !enabled);
  }

  showHint(text, ms = 4200) {
    const h = $('hint');
    h.textContent = text;
    h.classList.add('show');
    clearTimeout(this.hintTimer);
    this.hintTimer = setTimeout(() => h.classList.remove('show'), ms);
  }

  // ---------------- toasts / floats ----------------
  toast(text, kind = '', icon = '') {
    const el = document.createElement('div');
    el.className = `toast ${kind}`;
    el.innerHTML = `${icon ? `<span class="ti">${icon}</span>` : ''}<span>${text}</span>`;
    this.toastEl.appendChild(el);
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 380);
    }, 3000);
    while (this.toastEl.children.length > 4) this.toastEl.firstElementChild.remove();
  }

  float(text, worldPos, cls = '') {
    const v = worldPos.clone().project(this.game.camera);
    if (v.z > 1) return;
    const x = (v.x * 0.5 + 0.5) * window.innerWidth;
    const y = (-v.y * 0.5 + 0.5) * window.innerHeight;
    const el = document.createElement('div');
    el.className = `float ${cls}`;
    el.textContent = text;
    el.style.left = `${x}px`;
    el.style.top = `${y}px`;
    this.floatEl.appendChild(el);
    setTimeout(() => el.remove(), 1200);
  }

  // ---------------- modal core ----------------
  openSheet(html, kind, extraClass = '') {
    this.modalKind = kind;
    this.modal.classList.remove('hidden');
    this.modal.innerHTML = `<div class="sheet ${extraClass}" role="dialog" aria-modal="true">${html}</div>`;
    this.game.setPaused(true);
  }

  closeModal() {
    this.modal.classList.add('hidden');
    this.modal.innerHTML = '';
    this.modalKind = null;
    this.game.setPaused(false);
    this.game.audio.sfx('click');
  }

  header(icon, title, subtitle) {
    return `<div class="sheet-head">
      <div class="sigil">${icon}</div>
      <div><h2>${title}</h2><p>${subtitle}</p></div>
      <button class="close-x" data-close aria-label="Close">✕</button>
    </div>`;
  }

  // ---------------- shop ----------------
  openShop() {
    this.shopTab = 'buy';
    this.renderShop();
    this.game.audio.sfx('magic');
  }

  renderShop() {
    const g = this.game;
    const s = g.state;
    const items = g.shopItems();
    let body;
    if (this.shopTab === 'buy') {
      body = `<div class="shop-grid">${items.map((it, idx) => {
        const afford = s.gold >= it.price && it.available !== false;
        return `<div class="shop-item">
          <div class="si-ico">${it.icon}</div>
          <div class="si-main">
            <div class="si-name">${it.name}</div>
            <div class="si-desc">${it.desc}</div>
          </div>
          <button class="si-buy" data-buy="${idx}" ${afford ? '' : 'disabled'}>${it.available === false ? 'Sold out' : `${it.price} ◈`}</button>
        </div>`;
      }).join('')}</div>`;
    } else {
      const rows = Object.entries(CROPS).map(([type, c]) => {
        const n = s.crops[type] || 0;
        return `<div class="sell-row">
          <span class="si-ico" style="width:32px;height:32px;font-size:18px;display:grid;place-items:center">${c.icon}</span>
          <span class="n">${c.name}</span><span class="c">× ${n}</span><span class="v">${c.sell} ◈ each</span>
        </div>`;
      }).join('');
      const mats = `<div class="sell-row"><span class="n">🪵 Wood</span><span class="c">× ${s.wood}</span><span class="v">4 ◈ each</span></div>
        <div class="sell-row"><span class="n">🪨 Stone</span><span class="c">× ${s.stone}</span><span class="v">6 ◈ each</span></div>`;
      body = `${rows}${mats}
        <div style="display:flex;gap:8px;margin-top:10px">
          <button class="btn ghost" style="min-width:0;flex:1;padding:9px;font-size:12.5px" data-sell="crops">Sell All Crops</button>
          <button class="btn ghost" style="min-width:0;flex:1;padding:9px;font-size:12.5px" data-sell="mats">Sell Materials</button>
        </div>
        <p style="font-size:10.5px;color:#8fa0b1;margin:10px 2px 0;line-height:1.5">Zephyr pays a fair price. Moonpetal 58◈ · Sunberry 126◈ · Starcorn 275◈.</p>`;
    }
    const html = `${this.header('🪄', "Zephyr's Arcane Goods", 'Seeds, charms & curious things')}
      <div class="sheet-body">
        <div class="tabs">
          <button class="tab ${this.shopTab === 'buy' ? 'active' : ''}" data-tab="buy">Buy</button>
          <button class="tab ${this.shopTab === 'sell' ? 'active' : ''}" data-tab="sell">Sell</button>
        </div>
        ${body}
      </div>
      <div class="sheet-foot">
        <span style="font-size:11px;color:#9fb0c2;letter-spacing:.06em">YOUR PURSE</span>
        <div class="purse"><span class="gold"><span class="gem">◈</span> <b>${Math.floor(s.gold)}</b></span><span class="essence"><span class="star">✦</span> <b>${s.essence}</b></span></div>
      </div>`;
    this.openSheet(html, 'shop');

    this.modal.querySelectorAll('[data-buy]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const it = g.shopItems()[Number(btn.dataset.buy)];
        if (g.buy(it)) { this.renderShop(); this.update(g.state); }
      });
    });
    this.modal.querySelectorAll('[data-sell]').forEach((btn) => {
      btn.addEventListener('click', () => {
        g.sellAll(btn.dataset.sell);
        this.renderShop();
        this.update(g.state);
      });
    });
  }

  // ---------------- menu ----------------
  openMenu() {
    this.questTab = 'quests';
    this.renderMenu();
  }

  renderMenu() {
    const g = this.game;
    const s = g.state;
    let content = '';
    if (this.questTab === 'quests') {
      content = g.questList().map((q) => {
        const p = Math.min(1, q.progress / q.target);
        return `<div class="quest-item ${q.done ? 'done' : ''}">
          <div class="qi-top"><span class="qi-name">${q.name}</span><span class="qi-reward">${q.rewardText || ''}</span></div>
          <div class="qi-desc">${q.desc}</div>
          <div class="qi-bar"><i style="width:${q.done ? 100 : p * 100}%"></i></div>
          <div class="qi-status">${q.done ? '✦ Completed' : `${Math.min(q.progress, q.target)} / ${q.target}`}</div>
        </div>`;
      }).join('');
    } else if (this.questTab === 'guide') {
      content = `<div class="help-grid">
        <div class="help-card"><h4>Move</h4><p>Joystick on touch, <span class="keyrow">W</span><span class="keyrow">A</span><span class="keyrow">S</span><span class="keyrow">D</span> on keyboard. Drag the world to orbit the camera, scroll to zoom.</p></div>
        <div class="help-card"><h4>Use &amp; Attack</h4><p><span class="keyrow">E</span> or the green button interacts with soil, trees, rocks, people and the cottage. <span class="keyrow">Space</span> or the sword button swings your blade.</p></div>
        <div class="help-card"><h4>Farming</h4><p>Till soil, pick a seed from the hotbar, plant, then water. Crops grow overnight <em>only if watered</em>. Rain waters everything for free.</p></div>
        <div class="help-card"><h4>Energy</h4><p>Every chore costs energy. Drink a Mana Potion, or sleep at the cottage door to start a new day with full energy.</p></div>
        <div class="help-card"><h4>The Vale</h4><p>Chop trees for wood, mine rocks for stone, and clear slimes in the Whisperwood for arcane essence. Zephyr's tower lies east.</p></div>
        <div class="help-card"><h4>Magic</h4><p>Offer essence at the Moonwell west of the farm for rain, vitality, or a permanent blessing. Buy sprinklers to water a 3×3 patch each dawn.</p></div>
      </div>
      <p style="font-size:11px;color:#8fa0b1;margin-top:10px;line-height:1.55">Phone tip: landscape gives the widest view. All progress saves automatically each morning and when you close a shop.</p>`;
    } else {
      content = `
        <div class="setting-row"><div><div class="sl">Sound</div><div class="sd">Procedural ambience, birds &amp; chimes</div></div><button class="toggle ${g.soundOn ? 'on' : ''}" data-setting="sound"></button></div>
        <div class="setting-row"><div><div class="sl">Save game</div><div class="sd">Stored locally in this browser</div></div><button class="btn ghost" style="min-width:0;padding:8px 12px;font-size:12px" data-save>Save now</button></div>
        <div class="setting-row"><div><div class="sl">New journey</div><div class="sd">Erase this save and start over</div></div><button class="danger-btn" data-newgame>Start over</button></div>
        <div class="setting-row" style="border-bottom:none"><div><div class="sl">Your story</div><div class="sd">Day ${s.day} · ${Math.floor(s.gold)} gold · ${s.stats.harvested} crops harvested · ${s.stats.slimes} slimes cleared</div></div></div>`;
    }
    const html = `${this.header('✦', 'Emberfall Vale', `Day ${s.day} · ${s.season} · ${s.weather === 'rain' ? 'Rainy' : 'Clear skies'}`)}
      <div class="sheet-body">
        <div class="tabs">
          <button class="tab ${this.questTab === 'quests' ? 'active' : ''}" data-qtab="quests">Quests</button>
          <button class="tab ${this.questTab === 'guide' ? 'active' : ''}" data-qtab="guide">Guide</button>
          <button class="tab ${this.questTab === 'settings' ? 'active' : ''}" data-qtab="settings">Options</button>
        </div>
        ${content}
      </div>
      <div class="sheet-foot">
        <span style="font-size:10.5px;color:#8fa0b1;letter-spacing:.06em">✦ ${s.essence} ESSENCE · 🪵 ${s.wood} · 🪨 ${s.stone}</span>
        <button class="btn primary" style="min-width:0;padding:9px 18px;font-size:13px" data-close>Resume</button>
      </div>`;
    this.openSheet(html, 'menu');
    const toggle = this.modal.querySelector('[data-setting="sound"]');
    if (toggle) toggle.addEventListener('click', () => {
      g.setSound(!g.soundOn);
      toggle.classList.toggle('on', g.soundOn);
    });
    const save = this.modal.querySelector('[data-save]');
    if (save) save.addEventListener('click', () => { g.save(); this.toast('Journey saved.', '', '💾'); });
    const ng = this.modal.querySelector('[data-newgame]');
    if (ng) ng.addEventListener('click', () => {
      if (confirm('Erase this save and begin a new journey?')) {
        this.closeModal();
        g.startNew();
      }
    });
  }

  openHelp() {
    this.questTab = 'guide';
    this.renderMenu();
  }

  // ---------------- dialog ----------------
  openDialog(opts) {
    const { title, portrait, text, options } = opts;
    const html = `<div class="sheet dialog-sheet">
      <div class="sheet-head">
        <div class="sigil">${portrait}</div>
        <div><h2>${title}</h2><p>${opts.subtitle || ''}</p></div>
        <button class="close-x" data-close aria-label="Close">✕</button>
      </div>
      <div class="sheet-body">
        <div class="dialog-body">
          <div class="portrait">${portrait}</div>
          <div class="dialog-text">${text}</div>
        </div>
        <div class="dialog-options">${options.map((o, i) => `<button class="dialog-opt" data-opt="${i}" ${o.disabled ? 'disabled' : ''}>${o.label}</button>`).join('')}</div>
      </div>
    </div>`;
    this.openSheet(html, 'dialog');
    this.modal.querySelectorAll('[data-opt]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const o = options[Number(btn.dataset.opt)];
        if (o.action) o.action();
        else this.closeModal();
      });
    });
  }

  // ---------------- shrine ----------------
  openShrine() {
    const g = this.game;
    const s = g.state;
    const awake = s.blessing >= 2;
    const html = `${this.header('✦', 'The Moonwell', 'An old magic sleeps beneath the stones')}
      <div class="sheet-body">
        <div class="dialog-body" style="margin-bottom:14px">
          <div class="portrait">🌙</div>
          <div class="dialog-text">The standing stones hum with a low, silver song. Offerings of <em>essence</em> are drawn into the floating crystal.
          <br /><br />You carry <em>${s.essence} essence</em>.</div>
        </div>
        <div class="shop-grid">
          <div class="shop-item">
            <div class="si-ico">🌧</div>
            <div class="si-main"><div class="si-name">Rite of Rain</div><div class="si-desc">Water every planted crop, and bring rain tomorrow morning.</div></div>
            <button class="si-buy" data-rite="rain" ${s.essence >= 2 ? '' : 'disabled'}>2 ✦</button>
          </div>
          <div class="shop-item">
            <div class="si-ico">💚</div>
            <div class="si-main"><div class="si-name">Vitality Offering</div><div class="si-desc">Restore your health and energy to full.</div></div>
            <button class="si-buy" data-rite="heal" ${s.essence >= 2 ? '' : 'disabled'}>2 ✦</button>
          </div>
          <div class="shop-item">
            <div class="si-ico">🌙</div>
            <div class="si-main"><div class="si-name">Awaken the Moonwell</div><div class="si-desc">A permanent blessing: +25 max energy and a sprinkler for your farm.${awake ? ' (Already awakened)' : ''}</div></div>
            <button class="si-buy" data-rite="awaken" ${!awake && s.essence >= 5 ? '' : 'disabled'}>${awake ? 'Done' : '5 ✦'}</button>
          </div>
        </div>
        <p style="font-size:10.5px;color:#8fa0b1;margin:11px 2px 0;line-height:1.5">Slimes in the Whisperwood drop essence. They grow bolder after dusk.</p>
      </div>`;
    this.openSheet(html, 'shrine');
    this.modal.querySelectorAll('[data-rite]').forEach((btn) => {
      btn.addEventListener('click', () => {
        g.shrineRite(btn.dataset.rite);
        this.openShrine();
        this.update(g.state);
      });
    });
  }

  // ---------------- sleep / summary ----------------
  sleepFade(on) {
    const f = $('screen-fade');
    f.classList.toggle('on', on);
  }

  showSummary(data, onClose) {
    const html = `<div class="sheet summary-sheet">
      <div class="sheet-body" style="padding-top:22px">
        <div class="weather-line">${data.weather === 'rain' ? '🌧 Rainy morning' : '☀ Clear morning'}</div>
        <div class="big-day">Day ${data.day}</div>
        <div style="font-family:var(--serif);font-size:13px;color:#a9bccd;margin-top:2px">${data.season} · Emberfall Vale</div>
        <div class="summary-list">
          ${data.crops ? `<div class="summary-line"><span>Crops grown</span><b>+${data.crops}</b></div>` : ''}
          <div class="summary-line"><span>Gold earned yesterday</span><b>${data.earned} ◈</b></div>
          <div class="summary-line"><span>Energy restored</span><b>${data.maxEnergy} ⚡</b></div>
          ${data.rain ? '<div class="summary-line"><span>The rain watered your crops</span><b>✓</b></div>' : ''}
          ${data.sprinklers ? `<div class="summary-line"><span>Sprinklers murmured to life</span><b>${data.sprinklers}×</b></div>` : ''}
        </div>
        <p class="summary-flavor">${data.flavor}</p>
        <button class="btn primary" id="btn-rise" style="width:100%;margin-top:6px">Rise and shine</button>
      </div>
    </div>`;
    this.openSheet(html, 'summary');
    const btn = this.modal.querySelector('#btn-rise');
    if (btn) btn.addEventListener('click', () => {
      this.closeModal();
      if (onClose) onClose();
    });
  }

  showWin() {
    const html = `<div class="sheet win-sheet">
      <div class="sheet-body" style="padding:24px 22px">
        <div class="win-crown">👑</div>
        <h2>The Ember Crown</h2>
        <p>You gathered the crown of woven starlight and set it upon the Moonwell. Magic spills back into Emberfall Vale — the fields glow, the Whisperwood sings, and the little farm that time forgot is forgotten no longer.</p>
        <p style="color:#ffdf9b;font-size:11px;letter-spacing:.14em;text-transform:uppercase;margin-top:16px">Vale restored · Day ${this.game.state.day}</p>
        <button class="btn primary" id="btn-keep-playing" style="width:100%;margin-top:18px">Keep tending the vale</button>
      </div>
    </div>`;
    this.openSheet(html, 'win');
    const btn = this.modal.querySelector('#btn-keep-playing');
    if (btn) btn.addEventListener('click', () => this.closeModal());
  }
}

