  background: radial-gradient(circle, rgba(29, 45, 66, .82), rgba(9, 15, 25, .8));
  color: rgba(239, 207, 138, .55); display: none;
  align-items: center; justify-content: center; font-size: 14px;
}
@media (pointer: coarse), (max-width: 860px) {
  .minimap-charm { display: flex; }
}
.minimap-charm .needle { position: absolute; inset: 0; transition: transform .25s; }
.minimap-charm .needle::before {
  content: ""; position: absolute; left: 50%; top: 3px; margin-left: -2px;
  border-left: 4px solid transparent; border-right: 4px solid transparent; border-bottom: 8px solid #8fe8c5;
}

/* ============ Toasts & floats ============ */
#toasts {
  position: fixed; left: 50%; top: calc(72px + var(--safe-t)); transform: translateX(-50%);
  z-index: 60; display: flex; flex-direction: column; align-items: center; gap: 7px;
  pointer-events: none; width: min(88vw, 460px);
}
.toast {
  display: flex; align-items: center; gap: 9px;
  padding: 8px 14px; border-radius: 10px;
  background: linear-gradient(135deg, rgba(20, 32, 49, .96), rgba(11, 18, 30, .96));
  border: 1px solid var(--line);
  color: #f0e7d5; font-size: 12.5px; line-height: 1.3;
  box-shadow: 0 8px 28px rgba(0,0,0,.42);
  animation: toastIn .3s cubic-bezier(.2,1.4,.4,1) both;
  backdrop-filter: blur(10px);
  text-align: center;
}
.toast.out { animation: toastOut .35s ease forwards; }
.toast .ti { font-size: 17px; }
.toast.gold { border-color: rgba(239,207,138,.55); color: #ffe9b1; }
.toast.quest { border-color: rgba(126,226,178,.45); color: #c9f7de; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px) scale(.96); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px) scale(.97); } }

#floats { position: fixed; inset: 0; z-index: 55; pointer-events: none; overflow: hidden; }
.float {
  position: absolute; transform: translate(-50%, -50%);
  font-family: var(--serif); font-size: 14px; font-weight: 700; color: #ffe6a4;
  text-shadow: 0 2px 4px #000, 0 0 12px rgba(255,210,120,.4);
  animation: floatUp 1.15s ease-out forwards;
  white-space: nowrap;
}
.float.heal { color: #9bf0b8; }
.float.dmg { color: #ff8f83; }
.float.ess { color: #9be8ff; }
