.empty-note { text-align: center; color: #8fa0b2; font-size: 12.5px; padding: 22px 8px; line-height: 1.6; }

.quest-item { padding: 11px 12px; border-radius: 10px; border: 1px solid rgba(255,255,255,.07); background: rgba(255,255,255,.03); margin-bottom: 7px; }
.quest-item.done { border-color: rgba(126, 226, 178, .3); background: rgba(126, 226, 178, .06); }
.quest-item .qi-top { display: flex; align-items: baseline; gap: 7px; }
.quest-item .qi-name { font-family: var(--serif); font-size: 14.5px; color: #f2e9d7; flex: 1; }
.quest-item .qi-reward { font-size: 11px; color: var(--gold); white-space: nowrap; }
.quest-item .qi-desc { font-size: 11px; color: #98aabb; margin: 3px 0 6px; line-height: 1.4; }
.quest-item .qi-bar { height: 5px; border-radius: 3px; background: rgba(0,0,0,.4); overflow: hidden; }
.quest-item .qi-bar i { display: block; height: 100%; background: linear-gradient(90deg, #6fbf8f, #a9efc0); }
.quest-item .qi-status { font-size: 10px; margin-top: 4px; color: #8fd7a9; }
.quest-item.done .qi-status { color: #a9efc0; }

.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
@media (max-width: 520px) { .help-grid { grid-template-columns: 1fr; } }
.help-card { padding: 10px 11px; border-radius: 9px; background: rgba(255,255,255,.035); border: 1px solid rgba(255,255,255,.07); }
.help-card h4 { margin: 0 0 4px; font-family: var(--serif); font-weight: 400; font-size: 12.5px; color: var(--gold); letter-spacing: .04em; }
.help-card p { margin: 0; font-size: 11px; color: #b3c2d1; line-height: 1.5; }
.keyrow { display: inline-block; min-width: 18px; text-align: center; padding: 1px 4px; border-radius: 4px; background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.16); font-size: 9.5px; margin: 0 1px; color: #e9dfc9; }
.setting-row { display: flex; align-items: center; gap: 10px; padding: 10px 2px; border-bottom: 1px solid rgba(255,255,255,.06); }
