.setting-row .sd { font-size: 10.5px; color: #8fa0b1; }
.toggle { width: 44px; height: 24px; border-radius: 999px; border: 1px solid rgba(255,255,255,.2); background: rgba(0,0,0,.4); cursor: pointer; position: relative; transition: background .2s; flex: 0 0 auto; }
.toggle::after { content: ""; position: absolute; width: 18px; height: 18px; border-radius: 50%; top: 2px; left: 2px; background: #9aa8b8; transition: transform .2s, background .2s; }
.toggle.on { background: rgba(126, 226, 178, .3); border-color: rgba(126, 226, 178, .55); }
.toggle.on::after { transform: translateX(20px); background: #9bf0bc; }
