:root {
  --gold: #efcf8a;
  --gold-dim: #b9975b;
  --cream: #f6eedd;
  --ink: #0b111d;
  --panel: rgba(14, 22, 36, 0.94);
  --panel-2: rgba(23, 34, 52, 0.96);
  --line: rgba(239, 207, 138, 0.28);
  --green: #7fd6a8;
  --blue: #8fd0ff;
  --red: #ff8b7e;
  --shadow: 0 18px 60px rgba(0, 0, 0, 0.55);
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: ui-rounded, "SF Pro Rounded", "Segoe UI", system-ui, sans-serif;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  overflow: hidden; background: #0a0f19; color: var(--cream);
  font-family: var(--sans);
  overscroll-behavior: none;
  touch-action: none;
  user-select: none; -webkit-user-select: none;
}

#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

#vignette {
  position: fixed; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 42%, transparent 45%, rgba(5, 8, 15, 0.34) 100%),
    linear-gradient(to bottom, rgba(5, 8, 15, 0.16), transparent 18%, transparent 82%, rgba(5, 8, 15, 0.3));
}

.hidden { display: none !important; }

/* ============ HUD ============ */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; }

