/* phone breakpoints */
@media (max-width: 640px) {
  .title-inner { width: 100%; min-width: 0; }
  .title-inner h1 { font-size: clamp(40px, 12vw, 58px); letter-spacing: .01em; }
  .eyebrow { font-size: 8.5px; letter-spacing: .24em; }
  .hud-top-left { width: min(230px, 52vw); gap: 5px; }
  .quest-tracker { display: none; }
  .purse .mats { display: none; }
  .action-btn.interact { width: 78px; height: 78px; }
  .action-btn.attack { width: 58px; height: 58px; }
  .slot { width: 50px; height: 50px; border-radius: 10px; }
  .slot .seed { font-size: 20px; }
  .prompt { bottom: calc(112px + var(--safe-b)); font-size: 11.5px; }
  .hotbar { bottom: calc(12px + var(--safe-b)); }
  .prompt-key { display: none; }
  .minimap-charm { bottom: calc(200px + var(--safe-b)); }
  .title-inner h1 { font-size: clamp(52px, 16vw, 84px); }
  .btn { min-width: 200px; padding: 12px 20px; font-size: 14px; }
  .title-actions { width: 100%; }
  .btn { width: 100%; }
  .sheet-foot { padding: 9px 14px; }
  .sheet-body { padding: 12px 14px; }
}
/* portrait phones: lift the seed bar clear of the thumb controls */
@media (max-width: 640px) and (orientation: portrait) {
  .hotbar { bottom: calc(172px + var(--safe-b)); }
  .hotbar-label { display: none; }
  .prompt { bottom: calc(246px + var(--safe-b)); }
  .hint { bottom: calc(292px + var(--safe-b)); }
  #toasts { top: calc(106px + var(--safe-t)); }
  .minimap-charm { bottom: calc(252px + var(--safe-b)); }
